// Copy this file to terraform.tfvars and fill in your values

aws_region = "us-east-1"

// Daytona API Configuration
daytona_api_url = "https://daytona.example.com/api"
daytona_api_key = "[REDACTED]"

// Region Configuration
region_name          = "example-us-east-1"
proxy_url            = null // Set to enable proxy, e.g., "https://proxy.daytona.example.com"

// Snapshot Manager Configuration — REQUIRED. The snapshot registry is infrastructure this
// deployment depends on; the region is registered with this URL and resolves snapshots through it.
snapshot_manager_url = "https://snapshots.example.com"

// Runner Configuration
runner_instance_type = "m7i.2xlarge"
